function hRD = plugin_rd_rxtx_byte
% Reference design definition: ADRV9002 (ZCU102) Rx & Tx with a dedicated
% byte-stream DMA into the DUT -- the ZCU102 counterpart of the JUPITER byte
% reference design (AnalogDevices.jupiter.plugin_rd_rxtx_byte). It lets a
% ZCU102+ADRV9002 board run the SAME composite QPSK modem over the host byte
% DMA path, so it can transmit to / receive from a Jupiter board (two
% independent radios, untied clocks).
%
% Identical to plugin_rd_rxtx (the design string still contains 'Rx & Tx',
% so the common plugin normalizes ref_design to 'rxtx' and all stock BD
% branching applies), plus:
%   * a 'byte_dma' parameter -- it surfaces as a tcl variable in the BD
%     script scope, gating the axi_dmac + AXIS breakout instantiation in
%     matlab_processors.tcl (adrv9001/zcu102 case), so the four stock
%     designs never build the extra logic;
%   * four DUT byte interfaces wired to the breakout's plain pins: a
%     64-bit data word, an AXIS tvalid, a DUT-driven tready for true
%     backpressure, and a first-word marker (registered from tlast: the
%     beat after a transfer's last beat is word 1) so the DUT can
%     word-align the cyclic DMA stream to its packet boundary. One QPSK
%     packet payload (2240 bits) = exactly 35 words.
%
% plugin_rd('adrv9002', ...) maps the HDL project to 'adrv9001' and the
% carrier to 'zcu102' -- matching the matlab_processors.tcl switch case that
% holds the byte_dma-gated DMA block (tx_byte_dma 0x9D100000, rx_byte_dma
% 0x9D200000, byte_ctrl_gpio 0x9D300000), all clocked off
% axi_adrv9001/adc_1_clk.

% Call the common reference design definition function
hRD = AnalogDevices.plugin_rd('adrv9002', 'ZCU102', 'Rx & Tx, byte DMA');

% Gate for the BD-side DMA work (read as ::byte_dma in matlab_processors.tcl)
hRD.addParameter( ...
    'ParameterID',   'byte_dma', ...
    'DisplayName',   'Byte stream DMA', ...
    'DefaultValue',  'on');

% DUT-facing byte stream interfaces (byte_breakout pins are created by the
% byte_dma-gated block in matlab_processors.tcl)
hRD.addInternalIOInterface( ...
    'InterfaceID',         'Byte Data IN', ...
    'InterfaceType',       'IN', ...
    'PortName',            'dut_byte_data_in', ...
    'PortWidth',           64, ...
    'InterfaceConnection', 'byte_breakout/byte_data', ...
    'IsRequired',          false);
hRD.addInternalIOInterface( ...
    'InterfaceID',         'Byte Valid IN', ...
    'InterfaceType',       'IN', ...
    'PortName',            'dut_byte_valid_in', ...
    'PortWidth',           1, ...
    'InterfaceConnection', 'byte_breakout/byte_valid', ...
    'IsRequired',          false);
hRD.addInternalIOInterface( ...
    'InterfaceID',         'Byte Ready OUT', ...
    'InterfaceType',       'OUT', ...
    'PortName',            'dut_byte_ready_out', ...
    'PortWidth',           1, ...
    'InterfaceConnection', 'byte_breakout/byte_ready', ...
    'IsRequired',          false);
% NOTE: scalar interfaces keep their InterfaceID verbatim; only vector
% interfaces get the [0:N] suffix auto-appended (so 'Byte First IN' maps
% as-is in hdlworkflow, while 'Byte Data IN' surfaces as
% 'Byte Data IN [0:63]').
hRD.addInternalIOInterface( ...
    'InterfaceID',         'Byte First IN', ...
    'InterfaceType',       'IN', ...
    'PortName',            'dut_byte_first_in', ...
    'PortWidth',           1, ...
    'InterfaceConnection', 'byte_breakout/byte_first', ...
    'IsRequired',          false);

% Rx-side byte stream: DUT -> rx_byte_breakout (AXIS master) -> rx_byte_dma
% -> DDR. Same gating: rx_byte_breakout is created by the byte_dma block in
% matlab_processors.tcl. The DUT drives data/valid/last (tvalid must be one
% accepted beat per word -- the model-side beat gate guarantees it) and
% samples byte_ready (= the DMA's s_axis tready) for drop-on-stall.
hRD.addInternalIOInterface( ...
    'InterfaceID',         'Byte Data OUT', ...
    'InterfaceType',       'OUT', ...
    'PortName',            'dut_byte_data_out', ...
    'PortWidth',           64, ...
    'InterfaceConnection', 'rx_byte_breakout/byte_data', ...
    'IsRequired',          false);
hRD.addInternalIOInterface( ...
    'InterfaceID',         'Byte Valid OUT', ...
    'InterfaceType',       'OUT', ...
    'PortName',            'dut_byte_valid_out', ...
    'PortWidth',           1, ...
    'InterfaceConnection', 'rx_byte_breakout/byte_valid', ...
    'IsRequired',          false);
hRD.addInternalIOInterface( ...
    'InterfaceID',         'Byte Last OUT', ...
    'InterfaceType',       'OUT', ...
    'PortName',            'dut_byte_last_out', ...
    'PortWidth',           1, ...
    'InterfaceConnection', 'rx_byte_breakout/byte_last', ...
    'IsRequired',          false);
hRD.addInternalIOInterface( ...
    'InterfaceID',         'Byte User OUT', ...
    'InterfaceType',       'OUT', ...
    'PortName',            'dut_byte_user_out', ...
    'PortWidth',           1, ...
    'InterfaceConnection', 'rx_byte_breakout/byte_user', ...
    'IsRequired',          false);
hRD.addInternalIOInterface( ...
    'InterfaceID',         'Byte Ready IN', ...
    'InterfaceType',       'IN', ...
    'PortName',            'dut_byte_ready_in', ...
    'PortWidth',           1, ...
    'InterfaceConnection', 'rx_byte_breakout/byte_ready', ...
    'IsRequired',          false);
